 "content": "from collections import Counter, deque


def transform(grid):
    """Fill rectangular outlined frames, using 2 for 2x2 interiors and 7 otherwise."""
    h, w = len(grid), len(grid[0])
    counts = Counter(v for row in grid for v in row)
    bg = counts.most_common(1)[0][0]
    seen = set()
    out = [row[:] for row in grid]
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == bg or (r, c) in seen:
                continue
            comp = []
            q = deque([(r, c)])
            seen.add((r, c))
            while q:
                rr, cc = q.popleft()
                comp.append((rr, cc))
                for nr, nc in ((rr-1,cc),(rr+1,cc),(rr,cc-1),(rr,cc+1)):
                    if 0 <= nr < h and 0 <= nc < w and grid[nr][nc] == color and (nr,nc) not in seen:
                        seen.add((nr,nc))
                        q.append((nr,nc))
            r0 = min(rr for rr, _ in comp); r1 = max(rr for rr, _ in comp)
            c0 = min(cc for _, cc in comp); c1 = max(cc for _, cc in comp)
            if r1-r0 < 2 or c1-c0 < 2:
                continue
            # A frame is present when its complete outer perimeter has this color.
            perimeter = all(grid[rr][cc] == color
                            for rr in range(r0, r1+1) for cc in range(c0, c1+1)
                            if rr in (r0, r1) or cc in (c0, c1))
            if not perimeter:
                continue
            inner_area = (r1-r0-1) * (c1-c0-1)
            fill = 2 if inner_area == 4 else 7
            for rr in range(r0+1, r1):
                for cc in range(c0+1, c1):
                    out[rr][cc] = fill
    return out
